import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const PROCESSING_TYPES = ['미처리', '자동전표', '예외', '반제'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function isId(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isInteger(v) && v > 0;
  }
  return typeof v === 'string' && /^\d+$/.test(v) && v !== '0';
}

@Controller('api/v1')
export class FnSfr00703Controller {
  @Get('/bank-transactions')
  async listBankTransactions(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const fromDate = q['fromDate'];
    const toDate = q['toDate'];
    if (typeof fromDate !== 'string' || !DATE_PATTERN.test(fromDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일을 YYYY-MM-DD 형식으로 입력하세요.');
    }
    if (typeof toDate !== 'string' || !DATE_PATTERN.test(toDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 종료일을 YYYY-MM-DD 형식으로 입력하세요.');
    }
    const accountRaw = q['partnerAccountId'];
    const hasAccount = accountRaw !== undefined && accountRaw !== null && accountRaw !== '';
    if (hasAccount && !isId(accountRaw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '거래처 계좌 값이 올바르지 않습니다.');
    }
    const typeRaw = q['processingType'];
    const hasType = typeRaw !== undefined && typeRaw !== null && typeRaw !== '';
    if (hasType && !PROCESSING_TYPES.includes(String(typeRaw))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '처리 구분 값이 올바르지 않습니다.');
    }
    const pageRaw = q['page'];
    const sizeRaw = q['size'];
    const page = pageRaw === undefined || pageRaw === '' ? 0 : Number(pageRaw);
    let size = sizeRaw === undefined || sizeRaw === '' ? 20 : Number(sizeRaw);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 쪽 크기가 올바르지 않습니다.');
    }
    if (size > 200) {
      size = 200;
    }
    return transaction(async (db) => {
      const params: Record<string, unknown> = {
        fromDate,
        toDate,
        accountId: hasAccount ? String(accountRaw) : null,
        processingType: hasType ? String(typeRaw) : null,
        limit: size,
        offset: page * size,
      };
      const where =
        'WHERE transaction_at >= CAST(:fromDate AS date)' +
        ' AND transaction_at < CAST(:toDate AS date) + 1' +
        ' AND (CAST(:accountId AS bigint) IS NULL OR partner_account_id = CAST(:accountId AS bigint))' +
        ' AND (CAST(:processingType AS varchar) IS NULL OR processing_type = CAST(:processingType AS varchar))';
      const items = await db.query(
        'SELECT bank_transaction_id AS "bankTransactionId",' +
          ' partner_account_id AS "partnerAccountId",' +
          ' transaction_at AS "transactionAt",' +
          ' deposit_amount AS "depositAmount",' +
          ' withdrawal_amount AS "withdrawalAmount",' +
          ' summary AS "summary",' +
          ' counterparty_name AS "counterpartyName",' +
          ' processing_type AS "processingType"' +
          ' FROM bank_transaction ' +
          where +
          ' ORDER BY transaction_at DESC, bank_transaction_id DESC' +
          ' LIMIT :limit OFFSET :offset',
        params,
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM bank_transaction ' + where,
        params,
      );
      const total = Number(counts[0]['total']);
      return { items, page, size, total };
    });
  }

  @Post('/bank-transactions/:bankTransactionId/settle')
  @HttpCode(200)
  async settleBankTransaction(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const idRaw = req.params['bankTransactionId'];
    if (!isId(idRaw)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '거래내역 ID가 올바르지 않습니다.');
    }
    const targets = data['settlementTargetIds'];
    if (!Array.isArray(targets) || targets.length === 0) {
      throw new ApiError(422, 'SETTLEMENT_TARGET_INVALID', '반제할 채권·채무 항목을 선택하세요.');
    }
    if (!targets.every((t: unknown) => isId(t))) {
      throw new ApiError(422, 'SETTLEMENT_TARGET_INVALID', '반제 대상 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT bank_transaction_id AS "id", processing_type AS "processingType",' +
          ' journal_voucher_id AS "voucherId",' +
          ' COALESCE(deposit_amount, withdrawal_amount, 0) AS "amount"' +
          ' FROM bank_transaction WHERE bank_transaction_id = CAST(:id AS bigint) FOR UPDATE',
        { id: String(idRaw) },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'BANK_TRANSACTION_NOT_FOUND', '거래내역을 찾을 수 없습니다.');
      }
      const row = rows[0];
      // 반제는 예외 거래내역에서만 가능하다.
      if (row['processingType'] !== '예외') {
        throw new ApiError(409, 'BANK_TRANSACTION_ALREADY_PROCESSED', '예외 거래내역만 반제 처리할 수 있습니다. 이미 처리되었거나 반제 대상이 아닌 거래내역입니다.');
      }
      let voucherId: unknown = row['voucherId'];
      if (voucherId === null || voucherId === undefined) {
        // 가정: 반제 처리 시 전표 연결이 필수(CHECK)이므로 승인 상태의 수기(MANUAL) 전표를 만든다.
        const created = await db.query(
          'INSERT INTO journal_voucher (voucher_date, evidence_type, source_type, status,' +
            ' debit_total, credit_total, created_at, updated_at)' +
            " VALUES (CURRENT_DATE, '통장', 'MANUAL', '승인'," +
            ' CAST(:amount AS numeric), CAST(:amount AS numeric), now(), now())' +
            ' RETURNING journal_voucher_id AS "id"',
          { amount: String(row['amount']) },
        );
        voucherId = created[0]['id'];
      }
      const updated = await db.query(
        "UPDATE bank_transaction SET processing_type = '반제'," +
          ' journal_voucher_id = CAST(:voucherId AS bigint),' +
          ' processed_by_id = CAST(:userId AS bigint),' +
          ' processed_at = now(), updated_at = now()' +
          ' WHERE bank_transaction_id = CAST(:id AS bigint)' +
          ' RETURNING bank_transaction_id AS "bankTransactionId", processing_type AS "processingType"',
        { id: String(idRaw), voucherId: String(voucherId), userId: user.id },
      );
      return updated[0];
    });
  }
}

