import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const TYPES: [string, string][] = [
  ['미처리', '미처리'],
  ['자동전표', '자동전표'],
  ['예외', '예외'],
  ['반제', '반제'],
];

export default function FnSfr00703Page({ role, notify }: PageProps) {
  const [accountId, setAccountId] = useState<number | string>('');
  const [processingType, setProcessingType] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState(0);
  const [filterError, setFilterError] = useState('');
  const [selected, setSelected] = useState<Row | null>(null);
  const [targetText, setTargetText] = useState('');

  const { data, error, reload } = useData<Page>(async () => {
    if (!applied) {
      return { items: [], page: 0, size: 20, total: 0 };
    }
    return call<Page>('GET', '/bank-transactions', role, undefined, { ...applied, page, size: 20 });
  }, [applied, page, role]);

  const rows = data ? data.items : [];
  const exceptionCount = rows.filter((r) => r.processingType === '예외').length;

  function search() {
    if (!fromDate || !toDate) {
      setFilterError('조회 기간(시작일·종료일)을 입력하세요.');
      return;
    }
    setFilterError('');
    setPage(0);
    setApplied({ partnerAccountId: accountId, processingType, fromDate, toDate });
  }

  function reset() {
    setAccountId('');
    setProcessingType('');
    setFromDate('');
    setToDate('');
    setFilterError('');
    setApplied(null);
    setPage(0);
  }

  function openRow(row: Row) {
    setTargetText('');
    setSelected(row);
  }

  async function settle() {
    if (!selected) {
      return;
    }
    const ids = targetText
      .split(',')
      .map((s) => s.trim())
      .filter((s) => s !== '');
    if (ids.length === 0) {
      throw new Error('반제할 채권·채무 항목 ID를 입력하세요.');
    }
    if (!ids.every((s) => /^\d+$/.test(s))) {
      throw new Error('반제 대상 ID는 숫자를 쉼표로 구분해 입력하세요.');
    }
    await call('POST', '/bank-transactions/' + String(selected.bankTransactionId) + '/settle', role, {
      settlementTargetIds: ids.map((s) => Number(s)),
    });
    notify('반제 처리했습니다.');
    setSelected(null);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>거래 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={data ? data.total : 0} />],
            ['이 쪽의 예외 거래', <Num value={exceptionCount} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>은행 거래내역</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="거래처 계좌">
            <LookupSelect table="partner_account" role={role} value={accountId} onChange={setAccountId} />
          </Field>
          <Field label="처리 구분">
            <Select value={processingType} onChange={setProcessingType} options={TYPES} placeholder="전체" />
          </Field>
          <Field label="조회 시작일" required>
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
        </Filters>
        <ErrorText text={filterError || error} />
        <Band total={data ? data.total : 0} />
        <DataTable
          rows={rows}
          onRowClick={openRow}
          empty="조회된 거래내역이 없습니다. 기간을 지정해 조회하세요."
          columns={[
            { key: 'transactionAt', label: '거래일시', render: (r) => <DateText value={r.transactionAt} time /> },
            { key: 'partnerAccountId', label: '거래처 계좌', render: (r) => <RefName table="partner_account" role={role} value={r.partnerAccountId} /> },
            { key: 'depositAmount', label: '입금액', render: (r) => <Num value={r.depositAmount} /> },
            { key: 'withdrawalAmount', label: '출금액', render: (r) => <Num value={r.withdrawalAmount} /> },
            { key: 'summary', label: '적요' },
            { key: 'counterpartyName', label: '상대 예금주명' },
            { key: 'processingType', label: '처리 구분', render: (r) => <Badge value={r.processingType} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r.processingType === '예외' ? (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      openRow(r);
                    }}
                  >
                    반제 처리
                  </button>
                ) : null,
            },
          ]}
        />
        <Pager page={data ? data.page : 0} size={data ? data.size : 20} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {selected && (
        <Drawer title="거래내역 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['거래일시', <DateText value={selected.transactionAt} time />],
              ['거래처 계좌', <RefName table="partner_account" role={role} value={selected.partnerAccountId} />],
              ['입금액', <Num value={selected.depositAmount} />],
              ['출금액', <Num value={selected.withdrawalAmount} />],
              ['적요', String(selected.summary ?? '')],
              ['상대 예금주명', String(selected.counterpartyName ?? '')],
              ['처리 구분', <Badge value={selected.processingType} />],
            ]}
          />
          {selected.processingType === '예외' && (
            <Form onSubmit={settle} submit="반제 처리">
              <Field label="반제할 채권·채무 항목 ID 목록" required wide hint="숫자를 쉼표로 구분해 입력 (예: 101, 102)">
                <TextInput value={targetText} onChange={setTargetText} />
              </Field>
            </Form>
          )}
        </Drawer>
      )}
    </div>
  );
}
